import ProductListViewed from './product-list-viewed.js';
import { mapProductFields } from './product-fields.js';

/**
 * The list impression for a recommendation section (bought together, basket gap).
 *
 * Reports the canonical `Product List Viewed`: only the 30 catalogue names reach the
 * advertising channels, so the bespoke `Recommendation List Viewed` it replaces was
 * dropped before any pixel. The AI recommendation widgets already report this way.
 *
 * Extends the generic handler because a recommendation list IS a product list — the
 * `{page.slug}_{page.id}_{source}` id and the category parsed off the page title are
 * identical, so they are reused rather than restated.
 */
export default class RecommendationProductListViewed extends ProductListViewed {
    constructor(details) {
        // No `data`, because the products are mapped below rather than by the parent;
        // no `nextPage`, so the parent leaves `sorts` null.
        super({ data: [], source: details?.source });
        this.source = details?.source;
        this.recommendedProducts = details?.products ?? [];
        this.requestId = details?.request_id ?? null;
    }

    /**
     * The generic catalogue list carries its products under `data`, so `products` is
     * what tells a recommendation section's emit apart.
     *
     * Deliberately does NOT inherit the parent's page-slug guard: that suppresses the
     * homepage and wishlist for the catalogue list, but a recommendation impression is
     * real wherever the section renders.
     */
    static shouldSend(details) {
        return Array.isArray(details?.products) && !!details?.source;
    }

    toSegment() {
        const { properties } = super.toSegment();

        return {
            event: 'Product List Viewed',
            properties: {
                ...properties,
                source: this.source,
                request_id: this.requestId,
                // The parent reads these off `page.title`, which is right for a category
                // listing but not for a recommendation section: on a PDP it is the product
                // name, on the cart it is "Shopping cart". Reporting either as a category
                // would invent a category that does not exist.
                category: null,
                sub_category: null,
                // Mapped here rather than by the parent: `position` has to be the rank
                // WITHIN this section (bought together drops the main product, so the
                // catalogue `product.position` differs) and every item is a whole
                // product. Kept in the payload because Snapchat's LIST_VIEW route reads
                // item_id and number_items straight off this array.
                products: this.recommendedProducts.map((product, index) => ({
                    ...mapProductFields(product, index + 1),
                    variant: 'product',
                })),
            },
        };
    }
}
